*/
scwin.btn_self_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_self_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.win.closePopup()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf99001.btn_self_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.movePage
 * @author Inswave
 * @date 2026. 09. 29
 * @param div
 * @returns
 * @hidden N
*/
scwin.movePage = async function (div) {
    /* sdd-asis-lifecycle:begin movePage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const grpCd = ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).parent).form.dnld_grp_tp_cd.value;
    if (grpCd === '01' || grpCd === '02') {
        if (div === '01') {
            ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).parent).popupDownlist01();
            $c.win.closePopup();
        } else {
            await $c.win.alert("국세청 및 한국은행은 '기타기관'으로 접속 할 수 없습니다.");
        }
    } else {
        if (grpCd === '03') {
            if (div === '03') {
                ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).parent).popupDownlist03();
                $c.win.closePopup();
            } else {
                await $c.win.alert("기타기관은 '국세청 및 한국은행'으로 접속 할 수 없습니다.");
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};
